const learningReducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;

const anatomyData={
  body:['01','Body','The principal field of the saree. Colour, checks, stripes and repeated motifs establish its visual rhythm.','Look for how the field relates to the border rather than judging either in isolation.'],
  paar:['02','Paar · Border','The woven edge that frames the saree. Its width, technique and contrast often identify a regional design language.','Both long edges may coordinate—or use different colours in a Ganga Jamuna arrangement.'],
  pallu:['03','Pallu · Anchal','The expressive end worn over the shoulder. It often carries the richest motifs, supplementary weaving or zari composition.','Read it as the saree’s visual conclusion, not simply a decorative panel.'],
  pleats:['04','Pleats','The folded section arranged at the front waist. Fabric weight, body and border influence how the pleats fall.','A firm cotton holds architecture; a fluid silk produces a softer cascade.'],
  blouse:['05','Blouse piece','An optional matching or contrasting length supplied with some sarees. Many traditional sarees do not include one.','Always confirm inclusion in the product details rather than assuming.'],
  fall:['06','Fall','A protective strip traditionally stitched inside the lower edge to support the drape and reduce abrasion.','The fall is usually added during finishing; it is not the saree’s woven border.']
};
