const sareeWorld=document.querySelector('[data-saree-world]');
if(sareeWorld){const places={bengal:{kicker:'Shared Bengal · registered and living traditions',title:'Bengal & Bangladesh',copy:'Explore Dhaka and Narayanganj for Jamdani, Tangail for its eponymous weaving art, Hooghly for Dhaniakhali, Bishnupur for Baluchari, and Phulia–Shantipur for migrated and evolving Bengal weaving lineages.',tags:['Dhaka · Jamdani','Tangail','Hooghly · Dhaniakhali','Bishnupur · Baluchari','Phulia–Shantipur'],note:'Partition, migration and exchange make some Bengal textile histories shared or debated; the map names documented centres without assigning exclusive cultural ownership.'},odisha:{kicker:'Odisha · many distinct loom regions',title:'Odisha',copy:'Dhalapathar near Khordha, Sambalpur–Bargarh for Bandha, Nuapatna for tie-dye cloth, Sonepur for Bomkai-associated work, and Maniabandha for Khandua reveal a state of multiple techniques—not one generic “Odisha weave.”',tags:['Dhalapathar','Sambalpuri Bandha','Nuapatna','Bomkai','Khandua'],note:'Names, registered specifications and present production areas do not always align neatly; provenance should be checked tradition by tradition.'},varanasi:{kicker:'Uttar Pradesh · brocade workshops',title:'Varanasi',copy:'Banaras Brocades and Sarees connect Varanasi with silk, zari and figured weaving traditions developed through specialised workshops and artisan communities.',tags:['Banarasi','Katan','Brocade','Zari'],note:'A Banarasi-style design woven elsewhere is not automatically a product of the registered geography.'},central:{kicker:'Madhya Pradesh · two distinct centres',title:'Maheshwar & Chanderi',copy:'Maheshwar is associated with light, striped-border Maheshwari sarees; Chanderi with translucent silk-cotton cloth and delicate woven motifs.',tags:['Maheshwari','Chanderi'],note:'These are separate traditions with different materials, structures and registered identities.'},west:{kicker:'Gujarat & Maharashtra · resist and tapestry',title:'West India',copy:'Patan is known for double-ikat Patola, while Paithan and Yeola are associated with the tapestry-like Paithani saree tradition. Kota in neighbouring Rajasthan adds its checked Doria structure.',tags:['Patan Patola','Paithani','Kota Doria'],note:'Each name describes a specific regional lineage, not a general decorative look.'},deccan:{kicker:'Telangana & Karnataka · yarn before cloth',title:'The Deccan',copy:'Pochampally is celebrated for ikat; Ilkal, Gadwal and Narayanpet use distinctive joins, checks, borders and regionally specific loom practices.',tags:['Pochampally Ikat','Ilkal','Gadwal','Narayanpet'],note:'Ikat patterns are established by resist-dyeing yarn before it is woven.'},tamil:{kicker:'Tamil Nadu · silk and structural joins',title:'Tamil Nadu',copy:'Kanchipuram silk sarees are known for strong colour fields, zari and joining techniques such as korvai and petni; Madurai Sungudi and Kandangi represent very different cotton and resist traditions.',tags:['Kanchipuram','Madurai Sungudi','Kandangi'],note:'Tamil Nadu contains many saree centres; no single marker can stand for all of them.'},nepal:{kicker:'Nepal · regional textile culture',title:'Nepal',copy:'Sarees form part of Nepal’s wider dress culture. Palpa is especially associated with Palpali Dhaka, a distinct patterned textile used across garments and accessories rather than one single named saree type.',tags:['Saree dress culture','Palpali Dhaka'],note:'This entry distinguishes a regional textile identity from a claim of exclusive saree origin.'},pakistan:{kicker:'Pakistan · continuity, migration and shared lineages',title:'Pakistan',copy:'Sarees remain within parts of Pakistan’s cultural life. Karachi has sustained Banarsi-style weaving, while Sindh shares long textile histories—including bandhani and ajrak-associated cloth—with neighbouring western India.',tags:['Karachi Banarsi weaving','Sindh textile culture','Bandhani lineages'],note:'These are shared and migrated histories; “Banarsi-style” in Karachi is distinct from India’s registered Banaras geographical indication.'},srilanka:{kicker:'Sri Lanka · a distinctive regional drape',title:'Sri Lanka',copy:'The Kandyan saree, or osariya, is associated with Kandy and recognised by its distinctive silhouette and midriff frill; it is a drape tradition rather than a named Indian-style weave.',tags:['Kandy · Osariya','Kandyan saree'],note:'The historical formation of the osariya includes regional and cross-cultural influence, so the map avoids a simplistic single-invention claim.'}};const controls=[...sareeWorld.querySelectorAll('[data-place]')],kicker=sareeWorld.querySelector('[data-map-kicker]'),title=sareeWorld.querySelector('[data-map-title]'),copy=sareeWorld.querySelector('[data-map-copy]'),tags=sareeWorld.querySelector('[data-map-tags]'),note=sareeWorld.querySelector('[data-map-note]'),map=sareeWorld.querySelector('.saree-world-map');function select(key){const p=places[key];if(!p)return;controls.forEach(c=>{const active=c.dataset.place===key;c.classList.toggle('is-active',active);c.setAttribute('aria-pressed',String(active))});map.dataset.activePlace=key;kicker.textContent=p.kicker;title.textContent=p.title;copy.textContent=p.copy;tags.replaceChildren(...p.tags.map(t=>{const s=document.createElement('span');s.textContent=t;return s}));note.textContent=p.note;sareeWorld.querySelector('.saree-world-card').classList.remove('is-changing');requestAnimationFrame(()=>sareeWorld.querySelector('.saree-world-card').classList.add('is-changing'))}controls.forEach(c=>c.addEventListener('click',()=>select(c.dataset.place)));select('bengal')}

