/* Clickable chronology: one focused story per group, without hiding any content. */
function makeChronologyInteractive(selector){
  const items=[...document.querySelectorAll(selector)];
  items.forEach(item=>{
    item.tabIndex=0;
    item.setAttribute('role','button');
    item.setAttribute('aria-pressed','false');
    const toggle=()=>{
      const active=!item.classList.contains('is-selected');
      items.forEach(peer=>{peer.classList.remove('is-selected');peer.setAttribute('aria-pressed','false')});
      if(active){item.classList.add('is-selected');item.setAttribute('aria-pressed','true')}
    };
    item.addEventListener('click',toggle);
    item.addEventListener('keydown',event=>{
      if(event.key==='Enter'||event.key===' '){event.preventDefault();toggle()}
    });
  });
}
makeChronologyInteractive('.weave-map-list>li');
makeChronologyInteractive('.weave-constellation>div');
makeChronologyInteractive('.textile-timeline .timeline-entry');
